import { useState } from "react";
import "../styles/DictionaryModal.css";

export function DictionaryModal() {
  const [word, setWord] = useState("");
  const [result, setResult] = useState(null);
  const [isOpen, setIsOpen] = useState(true);

  const handleLookup = () => {
    if (!word.trim()) return;

    // Giả lập kết quả từ điển
    const fakeResult = {
      word: word,
      phonetic: "/demo/",
      pos: "noun",
      definition: `This is a sample definition of "${word}".`,
      example: `Here is an example sentence with the word "${word}".`,
    };

    setResult(fakeResult);
  };

  if (!isOpen) return null;

  return (
    <div className="dictionary-modal-overlay">
      <div className="dictionary-modal">
        <div className="modal-header">
          <h3>📚 Dictionary Lookup</h3>
          <button className="close-button" onClick={() => setIsOpen(false)}>
            ✕
          </button>
        </div>

        <div className="modal-body">
          <input
            type="text"
            value={word}
            onChange={(e) => setWord(e.target.value)}
            placeholder="Type a word..."
          />
          <button onClick={handleLookup}>Search</button>

          {result && (
            <div className="dictionary-result">
              <h4>{result.word} {result.phonetic}</h4>
              <p><em>{result.pos}</em></p>
              <p>{result.definition}</p>
              <p><strong>Example:</strong> {result.example}</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
